def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Identify colored vertical edge runs, which form the two opposing bands.
    edge_runs = []
    for side, col in [('left', 0), ('right', w - 1)]:
        rows = [r for r in range(h) if grid[r][col] not in (8, 2)]
        runs = []
        for r in rows:
            if not runs or r != runs[-1][-1] + 1:
                runs.append([r])
            else:
                runs[-1].append(r)
        for run in runs:
            edge_runs.append((side, run[0], run[-1]))
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    # Pair each point's edge run with the opposing run, using their row offset
    # to echo the stripe in the other band.
    for r, c in points:
        side = None
        run = None
        for s, a, b in edge_runs:
            if a <= r <= b:
                side, run = s, (a, b)
                break
        if side is None:
            continue
        if side == 'right':
            for x in range(c + 1, w - 1):
                out[r][x] = 2
            out[r][c] = 4
            opp = next(((s, a, b) for s, a, b in edge_runs if s == 'left'), None)
            if opp:
                _, a, b = opp
                rr = a + (r - run[0])
                if a <= rr <= b:
                    for x in range(1, w):
                        out[rr][x] = 2
        else:
            for x in range(c - 1, 0, -1):
                out[r][x] = 2
            out[r][c] = 4
            opp = next(((s, a, b) for s, a, b in edge_runs if s == 'right'), None)
            if opp:
                _, a, b = opp
                rr = a + (r - run[0])
                if a <= rr <= b:
                    for x in range(0, w - 1):
                        out[rr][x] = 2
    return out

