    # The two edge bars launch straight rays into the field. Isolated interior
    # marks are the ray color; a hit is marked with 4 and terminates that ray.
    edge_colors = set()
    edges = []
    for side in ('top', 'bottom', 'left', 'right'):
        coords = range(w) if side in ('top', 'bottom') else range(h)
        fixed = 0 if side in ('top', 'left') else (h - 1 if side == 'bottom' else w - 1)
        vals = [grid[fixed][i] if side in ('top', 'bottom') else grid[i][fixed] for i in coords]
        runs = []
        start = None
        for i, v in enumerate(vals + [bg]):
            if i < len(vals) and v != bg:
                edge_colors.add(v)
                if start is None:
                    start = i
            elif start is not None:
                runs.append((start, i - 1))
                start = None
        for a, b in runs:
            edges.append((side, a, b))

