    markers = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == ray_color}
    many_marks = len(markers) > 1

    for side, a, b in edges:
        # Horizontal edge bars project on globally even columns; vertical bars
        # project on every marked row for multi-hit patterns, otherwise even rows.
        if side in ('top', 'bottom'):
            positions = [c for c in range(a, b + 1) if c % 2 == 0]
        else:
